mapper.select:
SELECT ID, USER_ID, USER_NAME, PRODUCT_ID, RATING, CONTENT, REG_DATE, UPD_DATE
FROM TB_REVIEW
WHERE PRODUCT_ID = #{productId}
ORDER BY REG_DATE DESC

    LIMIT #{limit}


    OFFSET #{offset}

SELECT COUNT(*)
FROM TB_REVIEW
WHERE PRODUCT_ID = #{productId}

mapper.insert:
INSERT INTO TB_REVIEW ( PRODUCT_ID
                      , USER_NAME
                      , RATING
                      , CONTENT
                      , REG_DATE)
VALUES ( #{productId}
       , #{userName}
       , #{rating}
       , #{content}
       , NOW())

mapper.update:
UPDATE TB_REVIEW
SET RATING = #{rating}
  , CONTENT = #{content}
  , UPD_DATE = NOW()
WHERE ID = #{id}
  AND USER_NAME = #{userName}

mapper.delete:
DELETE
FROM TB_REVIEW
WHERE ID = #{id}
  AND USER_NAME = #{userName}
